function laInit(w,h,nAnts){
  w=Math.max(8,Math.floor(w)); h=Math.max(8,Math.floor(h));
  nAnts=Math.max(1,Math.min(8,Math.floor(nAnts)||1));
  var grid=[];
  for(var y=0;y<h;y++){ var row=[]; for(var x=0;x<w;x++){ row.push(0); } grid.push(row); }
  var ants=[];
  for(var i=0;i<nAnts;i++){
    ants.push({ x: Math.floor(w/2 + (i%4)*7 - 10), y: Math.floor(h/2 + Math.floor(i/4)*7 - 3), dir: i%4 });
  }
  ants=ants.map(function(a){ return { x:((a.x%w)+w)%w, y:((a.y%h)+h)%h, dir:a.dir }; });
  return { w:w, h:h, grid:grid, ants:ants, steps:0 };
}
function laStep(st){
  var grid=st.grid.map(function(row){ return row.slice(); });
  var dx=[0,1,0,-1], dy=[-1,0,1,0];
  var ants=st.ants.map(function(a){
    var cell=grid[a.y][a.x];
    var dir = cell===0 ? (a.dir+1)%4 : (a.dir+3)%4;
    grid[a.y][a.x] = cell===0 ? 1 : 0;
    var nx=((a.x+dx[dir])%st.w+st.w)%st.w;
    var ny=((a.y+dy[dir])%st.h+st.h)%st.h;
    return { x:nx, y:ny, dir:dir };
  });
  return { w:st.w, h:st.h, grid:grid, ants:ants, steps:st.steps+1 };
}
function laRun(st,n){ for(var i=0;i<n;i++){ st=laStep(st); } return st; }
function laCount(st){ var c=0; for(var y=0;y<st.h;y++){ for(var x=0;x<st.w;x++){ if(st.grid[y][x]) c++; } } return c; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { laInit:laInit, laStep:laStep, laRun:laRun, laCount:laCount };
}
if (typeof window !== 'undefined') {
  window.LangtonForgePure = { laInit:laInit, laStep:laStep, laRun:laRun, laCount:laCount };
}
